export const INSURANCE_TYPE = ({ product, category }) => {
  switch (product.code) {
    case CAR_PROTECTION:
      return [
        {
          title: LANG_STRINGS.individualPolicy,
          imgUrl: FILE_BLACK,
          type: NEW_PURCHASE,
        },
        ...(process.env.REACT_APP_SHOW_OFFLINE === 'true' &&
        process.env.REACT_APP_SHOW_OFFLINE_FLEET === 'true'
          ? [
              {
                title: LANG_STRINGS.fleetPolicy,
                imgUrl: COPY_BLACK,
                type: FLEET_POLICY,
              },
            ]
          : []),
      ]
    default:
      return []
  }
}

