import { EXTENDED_WARRANTY_ACTIONS } from './actions'

export const INITIAL_STATE = {

}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case EXTENDED_WARRANTY_ACTIONS.GET_VEHICLE_BRAND:
    case EXTENDED_WARRANTY_ACTIONS.GET_VEHICLE_VARIANT:
    case EXTENDED_WARRANTY_ACTIONS.CREATE_DRAFT_QUOTATION:
    case EXTENDED_WARRANTY_ACTIONS.GET_REGION_CODE:
    case EXTENDED_WARRANTY_ACTIONS.GET_PACKAGES:
    case EXTENDED_WARRANTY_ACTIONS.GET_EW_DETAILS:
    case EXTENDED_WARRANTY_ACTIONS.UPDATE_EXTENDED_WARRANTY_DRAFT:
    case EXTENDED_WARRANTY_ACTIONS.GET_PACKAGES_DETAIL:
    case EXTENDED_WARRANTY_ACTIONS.SHARE_DRAFT_QUOTE:
    case EXTENDED_WARRANTY_ACTIONS.GET_CUSTOMER_EW_DETAILS:
    case EXTENDED_WARRANTY_ACTIONS.GET_DOWNLOAD_EW_DRAFT_PDF:
    case EXTENDED_WARRANTY_ACTIONS.UPDATE_CUSTOMER_EXTENDED_WARRANTY_DRAFT:
    case EXTENDED_WARRANTY_ACTIONS.COMPLETE_DRAFT:
    case EXTENDED_WARRANTY_ACTIONS.CUSTOMER_COMPLETE_DRAFT:
    case EXTENDED_WARRANTY_ACTIONS.PAY_LATER:
      return {
        ...state,
        ...payload
      }
    case EXTENDED_WARRANTY_ACTIONS.GET_VEHICLE_YEAR:
      return {
        ...state,
        getVehicleYearData: payload.getVehicleYearData?.reverse()
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
