import { useEffect, useState } from 'react'
import Accordion from './EwAccordion.js'
import { AccordionWrapper, AccordionHeading } from './index.style.js'

const AccordionComponent = ({  data = [], title = '' }) => {
  const [accData, setAccData] = useState(data)

  useEffect(() => {
    const updatedData = title === 'Daftar Benefit' ? accData.map(( curr) => {
        return {heading: Object.values(curr)[0], title: Object.values(curr)[1], data: Object.values(curr)[2],  url: Object.values(curr)[3]}
    }) : accData
    setAccData(updatedData)
  }, [])
  
  return (
      <AccordionWrapper>
        <AccordionHeading>
          {title}
        </AccordionHeading>
        {accData && accData.map((item) => {
          return (
            <>
              <Accordion heading ={item.heading} url={item.url} title={item.title} data={item.data} parentTitle={title}/>
            </>
          )
        })}
      </AccordionWrapper>
  )
}
export default AccordionComponent
