import { useCallback, useEffect, useRef, useState } from 'react'
import { Input, InputRow, Label, InputWrapper, Prefix } from './index.style'
import { Error } from '../../../../commonStyle/index.style'
import { COUNTRY_PREFIX } from './constants'

function InputPhoneNumber({
  className,
  name,
  placeholder,
  error,
  onChange,
  onClick,
  disabled,
  required,
  defaultValue,
  top,
  bottom,
  autocomplete,
}) {
  const stripPrefix = (val) => {
    if (!val) return ''
    return String(val).startsWith(COUNTRY_PREFIX)
      ? String(val).slice(COUNTRY_PREFIX.length)
      : String(val)
  }

  const [showLabel, setShowLabel] = useState(false)
  const [inputValue, setInputValue] = useState(stripPrefix(defaultValue))

  const ref = useRef(null)

  useEffect(() => {
    setInputValue(stripPrefix(defaultValue))
  }, [defaultValue])

  const onClickHandler = () => {
    setShowLabel(true)
    onClick && onClick()
  }

  const onChangeHandler = ({ value }) => {
    const digits = value.replace(/\D/g, '')
    setInputValue(digits)
    onChange && onChange({ value: digits ? COUNTRY_PREFIX + digits : '' })
  }

  const handleClickOutside = useCallback(
    (event) => {
      if (ref.current && !ref.current.contains(event.target)) {
        if (!inputValue) setShowLabel(false)
      }
    },
    [inputValue]
  )

  useEffect(() => {
    document.addEventListener('click', handleClickOutside, false)
    return () => document.removeEventListener('click', handleClickOutside, false)
  }, [handleClickOutside])

  const isActive = showLabel || !!inputValue

  return (
    <InputWrapper ref={ref} top={top} bottom={bottom} className={className}>
      <Label active={isActive}>{placeholder}</Label>
      <InputRow error={!!error} disabled={disabled}>
        <Prefix active={isActive} disabled={disabled}>
          {COUNTRY_PREFIX}
        </Prefix>
        <Input
          id={name}
          name={name}
          onClick={onClickHandler}
          value={inputValue}
          disabled={disabled}
          required={required}
          onValueChange={onChangeHandler}
          decimalScale={0}
          allowNegative={false}
          allowLeadingZeros
          error={!!error}
          autoComplete={autocomplete || 'chrome-off'}
          data-form-type="other"
          data-lpignore="true"
        />
      </InputRow>
      {error && <Error>{error}</Error>}
    </InputWrapper>
  )
}

export default InputPhoneNumber
