import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useExtendedWarrantyContextValue } from '../../context'
import { getVehicleYear, getVehicleBrand, getVehicleVariant, createDraftQuoteReq, getRegionalCodes, getPackagesList, getEwDetails, updateExtendedWarrantyDraft, getPackagesDetail, shareDraftQuoteEwToCustomerReq, getCustomerEwDetails, getEwDraftDownloadPdfReq, updateCustomerExtendedWarrantyDraft, completeDraft, payLaterRequest, CustomerCompleteDraft } from '../actions'

export const useExtendedWarrantyServiceCall = (actionsCall = () => {}) => {
  const [myState, dispatch] = useExtendedWarrantyContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  return [myState, request]
}

export const useGetVehicleYear = () => {
  return useExtendedWarrantyServiceCall(getVehicleYear)
}

