import DynamicForm from '../../'
import { AddressStyle } from './index.style'
import { getAddressForm } from '../../constants'
import {
  useGetProvinceList,
  useGetCityList,
  useValidatePostalCode,
} from '../../../AddressForm/state/hooks/useAddressForm'
import {
  useEffect,
  useCallback,
  useRef,
  forwardRef,
  useImperativeHandle,
} from 'react'
import {
  resetError,
  useErrorContextValue,
} from '@pasarpolis/common-react-hooks'
import { typeValid } from '../../../../helpers/validations'

function AddressContainer(
  {
    name,
    defaultValue = {},
    required,
    onChange = () => {},
    designV2,
    ...props
  },
  parentRef
) {
  const [{ getProvinceListData = [] }, getProvinceListRequest] =
    useGetProvinceList()
  const [{ getCityListData = [] }, getCityListRequest] = useGetCityList()
  const [, validatePostalCodeReq] = useValidatePostalCode()
  const that = useRef({})
  const formRef = useRef({})
  const formRefData = useRef({
    [name]: {},
  })
  const [
    {
      // GET_PROVINCE_LIST_ERROR, getProvinceListStatus,
      // GET_CITY_LIST_ERROR, getCityListStatus,
      validatePostalCodeStatus,
    },
    dispatchError,
  ] = useErrorContextValue()

  useImperativeHandle(parentRef, () => ({
    validateAddressForm: () => {
      const addressData = formRef.current[name].validateFormValues()
      return addressData
    },
  }))

  useEffect(() => {
    if (!formRefData.current[name].isDataCalled) {
      formRefData.current[name].isDataCalled = true
      getProvinceListRequest()
      if (defaultValue?.province_code && !that.current.city_code) {
        that.current = {
          city_code: {
            city_code: defaultValue.city_code,
            city_name: defaultValue.city_name,
            region: defaultValue.region,
          },
          province_code: {
            province_code: defaultValue.province_code,
            province_name: defaultValue.province_name,
          },
          postal_code: defaultValue.postal_code,
          address: defaultValue.address,
        }
        getCityListRequest({ province: defaultValue.province_code })
      }
    }
  }, [getProvinceListRequest, getCityListRequest, defaultValue, name])

  const updateAddressPostalCodeError = useCallback(
    (error) => {
      // handle error for postal code
      formRef.current[name].setErrorMap({
        postal_code: error,
      })
    },
    [name]
  )

  useEffect(() => {
    if (
      validatePostalCodeStatus === 'success' &&
      that.current.isPostalCodeApiCall
    ) {
      that.current.isAddressError = false
      that.current.isPostalCodeApiCall = false
      that.current.error = ''
      dispatchError(
        resetError({
          validatePostalCodeStatus: '',
        })
      )
    } else if (validatePostalCodeStatus && that.current.isPostalCodeApiCall) {
      that.current.isAddressError = true
      that.current.postal_code = null
      that.current.isPostalCodeApiCall = false
      that.current.error = validatePostalCodeStatus
      updateAddressPostalCodeError(validatePostalCodeStatus)
      dispatchError(
        resetError({
          validatePostalCodeStatus: '',
        })
      )
    }
  }, [validatePostalCodeStatus, updateAddressPostalCodeError, dispatchError])

  const handleOnChange = useCallback(
    (data) => {
      if (
        data?.province_code &&
        that.current?.province_code?.province_code !==
          data?.province_code?.province_code
      ) {
        that.current = {
          ...that.current,
          ...data,
        }
        if (that.current?.city_code?.city_code) {
          formRef.current[name].resetAutoSearch('city_code')
          delete that.current.city_code
        }
        getCityListRequest({ province: data?.province_code?.province_code })
        return
      }

      if (data?.city_code) {
        that.current = {
          ...that.current,
          ...data,
        }
      }

      if (data?.postal_code) {
        if (
          typeValid('postal_code', data?.postal_code) &&
          data?.postal_code !== that.current.postal_code
        ) {
          that.current.isPostalCodeApiCall = true
          validatePostalCodeReq({
            body: {
              postal_code: data?.postal_code,
            },
          })
        }
      }

      that.current = {
        ...that.current,
        ...data,
      }

      if (data?.address) {
        that.current.address = data?.address
      }
      onChange({
        ...that.current.province_code,
        ...that.current.city_code,
        postal_code: that.current.postal_code,
        address: that.current.address,
      })

      // if (that.current.province_code && that.current.city_code && that.current.postal_code && that.current.address) {
      // }
    },
    [getCityListRequest, validatePostalCodeReq, onChange, name]
  )

  return (
    <AddressStyle>
      <DynamicForm
        form={getAddressForm({
          getProvinceListData,
          getCityListData,
          defaultValue: that.current,
          required,
          designV2,
        })}
        onChange={handleOnChange}
        ref={(instance) => {
          formRef.current[name] = instance
        }}
      />
    </AddressStyle>
  )
}

export default forwardRef(AddressContainer)
