import { useRef, useImperativeHandle, forwardRef } from 'react'
import { AddressFormProvider } from '../../AddressForm/context'
import AddressContainer from './container'

function Address (props, parentRef) {
  const ref = useRef()

  useImperativeHandle(parentRef, () => ({
    validateAddressForm: () => {
      return ref.current.validateAddressForm()
    }
  }))

  return (
    <div>
      <AddressFormProvider>
        <AddressContainer {...props} ref={ref} />
      </AddressFormProvider>
    </div>
  )
}

export default forwardRef(Address)
