import { useCallback, useMemo, useRef, useState } from 'react'
import { useHistory } from 'react-router-dom'
import { connect } from 'react-redux'
import Cookies from 'universal-cookie'
import { DisplayFlexCCC } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import {
  INSURANCE_TYPE_COOKIES,
  LOGIN_AS_GURDIAN,
  GUARDIAN_PRODUCT_REDIRECT,
} from '../../../../../constants/cookies'
import {
  CAR_PROTECTION,
  PROPERTY_PROTECTION,
  FLEET_POLICY,
  MANUAL_ORDER,
  TRAVEL_PROTECTION,
  EXTENDED_WARRANTY_PROTECTION,
  NEW_PURCHASE,
  RENEW_PURCHASE,
  MV_RENEWAL_FLOW,
  OFFLINE_TO_ONLINE_PROTECTION,
} from '../../../../../constants/pkgCode'
import PolicyActions from '../../../../../redux/policy/action'
import { clearLocalStorage } from '../../../../../helpers/localstorage'
import Heading from '../../../../../components/Heading'
import MVChasisNumberCheckModal from '../../../../../components/MVChasisNumberCheckModal'
import useEventTracker from '../../../../../hooks/trackers'
import { INSURANCE_TYPE } from '../../constants'
import InsuranceTypeModal from '../InsuranceTypeModal'
import { checkIsLvAdmin } from '../../../../../helpers/checkAgentTags'
import { ProductStyle } from './index.style'
import { getProductsList } from './constants'

const cookies = new Cookies()

function Products({ isHideTitle, margin, agentData = {}, ...props }) {
  const that = useRef({})
  const history = useHistory()
  const { trackUserEvent } = useEventTracker()

  const productList = useMemo(() => getProductsList({ agentData }), [agentData])

  const [showInsuranceTypeModal, setShowInsuranceTypeModal] = useState(false)
  const [showMvChasisNumberCheckModal, setShowMvChasisNumberCheckModal] = useState(false)

  const handleProduct = useCallback(
    (product, type) => {
      cookies.set(INSURANCE_TYPE_COOKIES, product.code, { path: '/' })
      props.resetPolicyData(['packages'])
      props.saveAddonsToStore({})
      props.saveApplicationData({})
      switch (product.code) {
        case OFFLINE_TO_ONLINE_PROTECTION:
          return history.push('/offline/products')
        case PROPERTY_PROTECTION:
          return history.push(`/property/${product.code}/1/form`)
        case TRAVEL_PROTECTION:
          return history.push('/purchase/travel-protection/1')
        // return history.push('/travel')
        case EXTENDED_WARRANTY_PROTECTION:
          return history.push('/extended_warranty')
        case CAR_PROTECTION:
          if ([NEW_PURCHASE, RENEW_PURCHASE].includes(type)) {
            setShowInsuranceTypeModal(false)
            setShowMvChasisNumberCheckModal(true)
            return
          }
          if ([FLEET_POLICY, MANUAL_ORDER].includes(type)) {
            clearLocalStorage()
            history.push({
              pathname: `/${product.code}/${type}/order`,
              state: {
                productCode: product.code,
                purchaseType: type,
              },
            })
          }
          break
        default:
      }
    },
    [history, props]
  )

  const getProductStartPath = useCallback((product = {}) => {
    switch (product.code) {
      case PROPERTY_PROTECTION:
        return '/property/property-protection/1/form'
      case TRAVEL_PROTECTION:
        return '/purchase/travel-protection/1'
      case EXTENDED_WARRANTY_PROTECTION:
        return '/extended_warranty'
      case OFFLINE_TO_ONLINE_PROTECTION:
        return '/offline/products'
      case CAR_PROTECTION:
      default:
        return '/dashboard'
    }
  }, [])

  const handleSelectProduct = useCallback(
    (product = {}) => {
      trackUserEvent(`[Mitra] Homepage`, { product_key: product.code })
      that.current.product = product
      if (checkIsLvAdmin(agentData) && !cookies.get(LOGIN_AS_GURDIAN)) {
        cookies.set(INSURANCE_TYPE_COOKIES, product.code, { path: '/' })
        sessionStorage.setItem(GUARDIAN_PRODUCT_REDIRECT, getProductStartPath(product))
        history.push('/dependent/agents')
        return
      }
      if (product.code === CAR_PROTECTION) {
        setShowInsuranceTypeModal(!showInsuranceTypeModal)
        return
      }
      handleProduct(product)
    },
    [agentData, getProductStartPath, handleProduct, history, showInsuranceTypeModal, trackUserEvent]
  )

  const handleBeginMvPolicy = useCallback(
    (purchaseType, purchaseRenewFlow, vehicleData) => {
      setShowMvChasisNumberCheckModal(false)
      history.push({
        pathname: '/motor_vehicle/v2',
        state: {
          productCode: CAR_PROTECTION,
          purchaseType,
          purchaseRenewFlow,
          vehicleData,
        },
      })
    },
    [history]
  )

  return (
    <ProductStyle margin={margin}>
      {!isHideTitle && <Heading title="Beli Proteksi" />}
      <div className="product-listing">
        {productList?.length === 0 && (
          <div className="empty-product">Tidak ada Proteksi</div>
        )}
        {productList?.map((product, index) => {
          return (
            <DisplayFlexCCC
              key={`product_${index}`}
              className="product-container"
              onClick={() => handleSelectProduct(product)}
            >
              <DisplayFlexCCC className="product-img-box">
                {product.tag && <div className="badge-tag">{product.tag}</div>}
                <img
                  id={product.name}
                  src={product.logo}
                  className="product-images"
                  alt="product"
                  width={70}
                  height={70}
                />
              </DisplayFlexCCC>
              <CustomText
                color={AgentColorPallette.darkCharcoal}
                top="6px"
                textAlign="center"
                className="text-alignment"
              >
                {product.name}
              </CustomText>
            </DisplayFlexCCC>
          )
        })}
      </div>
      {showInsuranceTypeModal && (
        <InsuranceTypeModal
          onSubmit={(type) => handleProduct(that.current.product, type)}
          onClose={() => setShowInsuranceTypeModal(false)}
          showOptionModal={showInsuranceTypeModal}
          insuranceType={INSURANCE_TYPE({
            product: that.current.product,
            category: agentData.category,
          })}
        />
      )}
      {showMvChasisNumberCheckModal && (
        <MVChasisNumberCheckModal
          show={showMvChasisNumberCheckModal}
          renewalFlow={MV_RENEWAL_FLOW.EXISTING_CAR}
          onClose={() => setShowMvChasisNumberCheckModal(false)}
          onBeginNewPurchase={(vehicleData) => handleBeginMvPolicy(NEW_PURCHASE, null, vehicleData)}
          onBeginRenewal={(vehicleData) => {
            handleBeginMvPolicy(RENEW_PURCHASE, MV_RENEWAL_FLOW.EXISTING_CAR, vehicleData)
          }}
        />
      )}
    </ProductStyle>
  )
}

const { saveApplicationData, saveAddonsToStore, resetPolicyData } = PolicyActions

export default connect(() => ({}), {
  saveApplicationData,
  saveAddonsToStore,
  resetPolicyData,
})(Products)
