import { InputNumberStyle } from './index.style'
import FormItemLabel from '../FormItemLabel'
import NumberFormat from 'react-number-format'
import { useState, useCallback, useEffect, useRef, useImperativeHandle, forwardRef } from 'react'
import { LANG_STRINGS } from '../../../../lang/index'
import { Error, Row } from '../../../../commonStyle/index.style'
import { CustomText } from '../../..'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { MINI_INFO, VIEW_HIDDEN } from '../../../../images'

function InputNumber ({
  placeholder, error, subText,
  className, name, defaultValue, type, maxlength, isSkipRegex,
  opacity, title, required, disabled, onChange = () => {},
  onBlur = () => {}, hiddenIcon, autocomplete
}, parentRef) {
  const [inputValue, setInputValue] = useState(defaultValue || null)
  const [hiddenValue, setHiddenValue] = useState(true)
  const that = useRef({
    isDefaultSet: false
  })

  useImperativeHandle(parentRef, () => ({
    setInputValue
  }))

  useEffect(() => {
    if ((defaultValue || defaultValue === 0) && !inputValue && !that.current.isDefaultSet) {
      that.current.isDefaultSet = true
      setInputValue(defaultValue)
    }
  }, [defaultValue, inputValue])

  const handleInputChange = useCallback((e) => {
    const re = type === 'phone_number' ? /\+?\0?(62)?(62-)?[0-9]{0,17}$/ : /^[0-9\b]+$/
    if ((e.target.value === '' || re.test(e.target.value)) || isSkipRegex) {
      setInputValue(e.target.value)
      onChange(e)
    }
  }, [onChange, type, isSkipRegex])

  const handleValueChange = useCallback(({ value }) => {
    if (value < 0) return null
    setInputValue(value)

    if (value) {
      onChange(parseInt(value))
    } else {
      onChange('')
    }
  }, [onChange])

  const handleNPWPChange = useCallback(({ value }) => {
    setInputValue(value)
    if (value) {
      onChange(value)
    } else {
      onChange('')
    }
  }, [onChange])

  return (
    <InputNumberStyle
      error={error}
      className={className}
    >
      {
        title && (
          <FormItemLabel
            title={title}
            required={required}
          />
        )
      }
      {
        (type === 'amount') && (
          <NumberFormat
            thousandSeparator='.'
            decimalSeparator=','
            prefix='Rp '
            name={name}
            value={inputValue}
            disabled={disabled}
            onValueChange={handleValueChange}
            onBlur={onBlur}
            decimalScale={0}
            allowNegative={false}
            placeholder={placeholder || LANG_STRINGS.enterSomething}
            className='input-number'
            autoComplete={autocomplete || "chrome-off"}
            data-form-type="other"
            data-lpignore="true"
          />
        )
      }
      {
        type === 'phone_number' && (
          <input
            name={name}
            value={inputValue}
            placeholder={placeholder}
            className='input-number'
            disabled={disabled}
            inputMode='numeric'
            onBlur={onBlur}
            onChange={handleInputChange}
            maxLength={maxlength}
            autoComplete={autocomplete || "chrome-off"}
            data-form-type="other"
            data-lpignore="true"
          />
        )
      }
      {
        type === 'npwp' && (
          <NumberFormat
            name={name}
            value={inputValue}
            onValueChange={handleNPWPChange}
            disabled={disabled}
            decimalScale={0}
            placeholder={placeholder || LANG_STRINGS.enterSomething}
            className='input-number'
            format='################'
            autoComplete={autocomplete || "chrome-off"}
            data-form-type="other"
            data-lpignore="true"
          />
        )
      }
      {
        type === 'hidden' && (
          hiddenIcon ? (
            <Row justify='space-between'>
              <NumberFormat
                name={name}
                {...(hiddenValue ? { type: 'password' } : {})}
                value={inputValue}
                disabled={disabled}
                onChange={handleInputChange}
                decimalScale={0}
                allowLeadingZeros
                placeholder={placeholder || LANG_STRINGS.enterSomething}
                className='input-number width-100'
                autoComplete={autocomplete || "chrome-off"}
                data-form-type="other"
                data-lpignore="true"
              />
              <div className='icon-border' onClick={() => setHiddenValue(hidden => !hidden)}>
                <img src={VIEW_HIDDEN} alt='hidden' />
              </div>
            </Row>
          ) : (
            <NumberFormat
              name={name}
              type='password'
              value={inputValue}
              disabled={disabled}
              onChange={handleInputChange}
              decimalScale={0}
              allowLeadingZeros
              placeholder={placeholder || LANG_STRINGS.enterSomething}
              className='input-number'
              autoComplete={autocomplete || "chrome-off"}
              data-form-type="other"
              data-lpignore="true"
            />
          )
        )
      }
      {
        !type && (
          <NumberFormat
            name={name}
            value={inputValue}
            disabled={disabled}
            onChange={handleInputChange}
            decimalScale={0}
            placeholder={placeholder || LANG_STRINGS.enterSomething}
            className='input-number'
            autoComplete={autocomplete || "chrome-off"}
            data-form-type="other"
            data-lpignore="true"
          />
        )
      }
      {
        subText && (
          <CustomText
            color={AgentColorPallette.fontGrey}
            size='0.7em'
            top='0.4rem'
            className='display-flex flex-start'
          >
            <img src={MINI_INFO} alt='Info' />&nbsp;&nbsp;<span>{subText}</span>
          </CustomText>
        )
      }
      <Error>{error}</Error>
    </InputNumberStyle>
  )
}

export default forwardRef(InputNumber)
