import BottomActionSheet from '../../../../../components/BottomActionSheet'
import { Box, Box1, ButtonPadding, DesText, Image, Image1, ShareQuotationDiv, ShareQuotationStyle, Text, Text1, Top } from './index.style'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../lang/index'
import { Button, CustomText, } from '../../../../../components'
import { useCallback, useEffect, useRef, useState } from 'react'
import CircularLoader from '../../../../../components/CircularLoader'

import { useHistory, useParams } from 'react-router'
import { HOME_ICON, LINK_ICON, SENT_ICON, UMBRELLA_ICON } from '../../../../../images'
import { copySharingData } from '../../../../../helpers/utility'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { APP_HOST } from '../../../../../configs/url'
import { regex } from '../../../../../constants/regex'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import DynamicFormV3 from '../../../../../components/DynamicFormV3'
import { useGetEwDetails, useShareCustomerExtendedWarrantyQuote } from '../../state/hooks/useExtendedWarrantyState'
import { AgentColorPallette } from '../../../../../configs/colorPallete'

export const getShareQuotationWithCustomerTravel = () => ({
  fieldData: [
    {
      label: 'Nama Pelanggan',
      type: 'input',
      name: 'name',
      required: true,
    },
    {
      label: 'Nomor Ponsel',
      type: 'input',
      name: 'mobile_no',
      required: true,
      validator: (value = '') => {
        if (!(['+62', '62', '08'].some((pre) => value.startsWith(pre)))) return ERROR_LANG.phoneNumberNotStartsWith62
        if (value.startsWith('+62') && value.length > 15) return ERROR_LANG.max15DigitAllowed
        if (value.length > 14) return ERROR_LANG.max14DigitAllowed
        if (!regex.phoneRegex.test(value)) return ERROR_LANG.phoneNumberError
      }
    },
    {
      label: 'Email',
      type: 'input',
      name: 'email',
      required: true,
      validator: (value = '') => {
        if (!regex.emailRegex.test(value)) {
          return ERROR_LANG.emailRequiredError
        }
        return ''
      }
    }
  ]
})


function ShareQuotation({ show, onClose, loader }) {

  const formRef = useRef()
  const { id, draftId } = useParams()
  const history = useHistory()
  const { resetError } = useResetError()
  const [userBlurred, setUserBlurred] = useState(true)
  const [formValues, setFormValues] = useState({ name: '', email: '', mobile_no: '' })
  const [showShareDetailPopup, setShowShareDetailPopup] = useState(false)
  const [
    { getEwDetailsData = {} },
    getEwDetailsRequest
  ] = useGetEwDetails();
  const [{ shareDraftQuoteData = {} }, sendCustomerQuoteDraft] = useShareCustomerExtendedWarrantyQuote()
  const [{ shareDraftQuoteStatus }] = useErrorContextValue()


  const renderIconText = useCallback((icon, text) => {
    return (
      <Top
        paddingTop={'20px'}>
        <Image src={icon} alt={text} />
        <Text bold={700} size='10px'>
          {text}
        </Text>
      </Top>
    )
  }, [])

  const renderSentIcon = useCallback((icon, text) => {
    return (
      <Top >
        <Image1 src={icon} alt={text} />
      </Top>
    )
  }, [])

  useEffect(() => {
    if (shareDraftQuoteStatus !== 'success' && shareDraftQuoteStatus !== undefined) {
      ShowSnackbar.error({
        visible: true,
        text: `${ERROR_LANG.errorWhileUpdating}`
      })
    }
    else if (shareDraftQuoteStatus === 'success') {
      setShowShareDetailPopup(true)
    }
    resetError(['shareDraftQuoteStatus'])
  }, [shareDraftQuoteStatus, resetError])

  useEffect(() => {
    if (id) {
      getEwDetailsRequest({ draftQuoteId: id });
    }
  }, [getEwDetailsRequest, id]);

  useEffect(() => {
    if (getEwDetailsData.customer_detail.name) {
      setFormValues({
        name: getEwDetailsData.customer_detail.name,
        mobile_no: getEwDetailsData.customer_detail.mobile_no,
        email: getEwDetailsData.customer_detail.email,
      })
    }
  }, [getEwDetailsData]);

  const body = {
    customer_data: {
      email: formValues.email,
      mobile_no: formValues.mobile_no,
      name: formValues.name,
      ...getEwDetailsData?.customer_detail
    },
    draft_id: id ? id : draftId
  }

  const handleCustomerForm = (name, value) => {
    setFormValues({
      ...formValues,
      [name]: value,
    })
  }

  const handleSendQuote = () => {
    if (formValues) {
      sendCustomerQuoteDraft({
        body,
      })
    }
  }


  const getSharingData = (source) => {
    const linkOfShare = `${APP_HOST}/extended_warranty/draft/policy/${id || draftId}/?source=${source}`
    return {
      link: linkOfShare
    }
  }

  const handleCopyLink = () => {
    const sharingDate = getSharingData('quotation_copy')
    copySharingData(sharingDate.link)
    ShowSnackbar.success({
      visible: true,
      text: 'Menyalin ke clipboard berhasil'
    })
  }

  const handleNewPolicy = () => {
    history.push({
      pathname: `/extended_warranty`
    })
  }

  const handleBackHome = () => {
    history.push({
      pathname: `/dashboard`
    })
  }

  return (
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
      title={'Bagikan Penawaran'}
      zIndex={4}
      showHeader
      backGroundColor
    >
      {!showShareDetailPopup && (
        <>
          <ShareQuotationStyle>
            <CircularLoader isLoading={loader}>
              <DynamicFormV3
                formData={getShareQuotationWithCustomerTravel()}
                onChange={handleCustomerForm}
                ref={formRef}
                values={formValues}
                setUserBlurred={setUserBlurred}
              />
            </CircularLoader>
          </ShareQuotationStyle>
          <ButtonPadding>
            <Button
              onClick={handleSendQuote}
              textColor={'black'}
            >
              {LANG_STRINGS.share}
            </Button>
          </ButtonPadding>
        </>
      )
      }
      {showShareDetailPopup && (
        <>
          <ShareQuotationDiv>
            <Box1>
              <div className='box-adjust box-content'>
                {
                  renderSentIcon(
                    SENT_ICON,
                  )
                }
              </div>
            </Box1>
            <CustomText
              color={AgentColorPallette.darkCharcoal}
              weight={800}
              size='15px'
              textAlign='center'
            >
              {LANG_STRINGS.sentLink}
            </CustomText>
            <DesText>
              {LANG_STRINGS.qsText}
            </DesText>
            <Text bold={800} size='12px' lineHeight='12px'>
              {LANG_STRINGS.otherOptions}
            </Text>
            <Box>
              <div
                onClick={handleCopyLink}
                className='box-adjust box-content'>
                {
                  renderIconText(
                    LINK_ICON,
                    'SALIN TAUTAN PENAWARAN',
                  )
                }
              </div>
              <div
                onClick={handleNewPolicy}
                className='box-adjust box-content'>
                {
                  renderIconText(
                    UMBRELLA_ICON,
                    'BUAT PROTEKSI BARU',
                  )
                }
              </div>
              <div
                onClick={handleBackHome}
                className='box-adjust box-content'>

                {
                  renderIconText(
                    HOME_ICON,
                    'KEMBALI KE BERANDA',
                  )
                }
              </div>
            </Box>
          </ShareQuotationDiv>
          <ButtonPadding>
            <Button
              textColor={'black'}
              onClick={onClose}
            >
              TUTUP
            </Button>
          </ButtonPadding>
        </>
      )
      }
    </BottomActionSheet>
  )
}

export default ShareQuotation
