import {
  AccordionItems,
  AccordionTitle,
  AccordionData,
  AccDetailValue,
  Text,
  OrderedList,
  ChildOrderedList,
  AccordionHeading2,
} from "./index.style";

const Accordion = ({heading, url, title, data = [], parentTitle }) => {

  const renderComponent = (acc, index) => {   
    if (
      parentTitle === "Syarat & Ketentuan" ||
      parentTitle === "Prosedur, Tata Cara dan Syarat Pengajuan Klaim"
    ) {
      return Object.keys(acc)?.map((currItem) => {
        if (currItem === "ol" || currItem === "ol1" ) {
          return (
            <OrderedList>
              {Object.keys(acc[currItem])?.map((list) => {
                if (list.includes("childList")) {
                  return (
                    <ChildOrderedList>
                      {Object.keys(acc[currItem][list])?.map((lists) => {
                        return <li>{acc[currItem][list][lists]}</li>;
                      })}
                    </ChildOrderedList>
                  );
                }
                return <li>{acc[currItem][list]}</li>;
              })}
            </OrderedList>
          );
        }
        return <Text>{acc[currItem]}</Text>;
      });
    }
    else if (
      parentTitle === "Syarat & Ketentuan"
    ) {
      return Object.keys(acc)?.map((currItem) => {
        if (currItem === "ol") {
          return (
            <OrderedList>
              {Object.keys(acc[currItem])?.map((list) => {
                if (list.includes("childList")) {
                  return (
                    <ChildOrderedList>
                      {Object.keys(acc[currItem][list])?.map((lists) => {
                        return <li>{acc[currItem][list][lists]}</li>;
                      })}
                    </ChildOrderedList>
                  );
                }
                return <li>{acc[currItem][list]}</li>;
              })}
            </OrderedList>
          );
        }
        return <Text>{acc[currItem]}</Text>;
      });
    } 
    else {
      return (
        <AccordionData>
          <AccDetailValue>
              {`${index + 1}. ${acc}`}
          </AccDetailValue>
        </AccordionData>
      );
    }
  };

  return (
    <AccordionItems>
      {(parentTitle !== "Prosedur, Tata Cara dan Syarat Pengajuan Klaim" && <div>
      <img
      src={url} alt="icon"
      /></div>)}
      <div>  
      {parentTitle === "Syarat & Ketentuan" ? '' :<AccordionHeading2>
        {heading}
      </AccordionHeading2>}
      {parentTitle === "Syarat & Ketentuan" ? <AccordionHeading2>{title}</AccordionHeading2> : <AccordionTitle>
        {title}
      </AccordionTitle>}
      { data?.length && data?.map((acc, index) => renderComponent(acc, index))}
      </div>
    </AccordionItems>
  );
};
export default Accordion;
